var app=new Vue({el:"#app",delimiters:["[[","]]"],data:{loading:[],FB:{},model:{},scope:{},lgoptions:{scope:"email, public_profile, pages_read_user_content, pages_show_list, pages_manage_metadata, pages_manage_engagement, pages_messaging, pages_read_engagement"},listPages:[]},methods:{handleSdkInit({FB:a,scope:b}){this.FB=a,this.scope=b,this.FB.getLoginStatus(function(a){if("connected"===a.status){const b=a.authResponse.accessToken,c=window.location.origin+"/dashboard/settings/status";axios.post(c,{token:b}).catch(a=>{console.log(a)})}})},getListPage(){this.loading.push("Loading");const a=window.location.origin+"/dashboard/settings";axios.post(a,{token:this.FB.getAccessToken(),uid:this.FB.getUserID()}).then(a=>{this.loading.splice(0,1),this.listPages=a.data}).catch(a=>{console.log(a)})},sendPageUID(a){this.loading.push("Loading");const b=window.location.origin+"/dashboard/settings/"+this.listPages[a].uid;axios.put(b).then(a=>{this.loading.splice(0,1),this.listPages=a.data}).catch(a=>{console.log(a)})},getData(){const a=window.location.origin+"/dashboard/settings/data";axios.get(a).then(a=>{this.listPages=a.data}).catch(a=>{console.log(a)})},deletePage(){this.loading.push("Loading");const a=window.location.origin+"/dashboard/settings";axios.delete(a).then(a=>{this.loading.splice(0,1),this.listPages=a.data}).catch(a=>{console.log(a)})}},created(){this.getData()}});